#ifndef STORAGE_H
#define STORAGE_H

#include <stddef.h>
#include "ipc.h"
#include "log_record.h"

#define GT_BATCH_MAX_RECORDS 64   /* N */
#define GT_BATCH_MAX_AGE_S   60   /* T */

typedef struct gt_storage gt_storage;

/* Opens the segment dir and runs recovery before accepting data. */
gt_storage *gt_storage_open(const char *dir);
/* Scan one segment; truncate at the first bad record. */
gt_status   gt_storage_recover(const char *segment_path, size_t *removed_records);
gt_status   gt_storage_append(gt_storage *s, const gt_record *rec);
/* write() + fsync() the batch; a record is committed once this returns OK. */
gt_status   gt_storage_flush(gt_storage *s);
void        gt_storage_close(gt_storage *s);

#endif
#ifndef SUPERVISOR_H
#define SUPERVISOR_H

#include <stdint.h>
#include "ipc.h"

typedef struct gt_supervisor gt_supervisor;

gt_supervisor *gt_sup_create(void);
/* Register a child by argv; started in dependency order. */
gt_status      gt_sup_add_child(gt_supervisor *s, const char *name, char *const argv[]);
/* One poll() iteration: reap SIGCHLD, check heartbeats, restart with backoff. */
gt_status      gt_sup_step(gt_supervisor *s, uint64_t now_ms);
void           gt_sup_destroy(gt_supervisor *s);

#endif
#ifndef HUB_H
#define HUB_H

#include <stdint.h>
#include "ipc.h"
#include "log_record.h"

typedef struct gt_hub gt_hub;

gt_hub   *gt_hub_create(void);
/* Validate a sensor message, stamp seq + now_us, and fill the 24 B record
 * `out` that is forwarded to storage. */
gt_status gt_hub_accept(gt_hub *h, const gt_msg *in, uint64_t now_us, gt_record *out);
/* Per-sensor last-seen check; returns number of timed-out sensors. */
int       gt_hub_check_timeouts(gt_hub *h, uint64_t now_us);
void      gt_hub_destroy(gt_hub *h);

#endif
#ifndef LOG_RECORD_H
#define LOG_RECORD_H

#include <stddef.h>
#include <stdint.h>
#include "ipc.h"

/* On-disk format: see DESIGN.md "In what format". Little-endian, packed. */
#define GT_SEG_MAGIC      "GTLG"
#define GT_SEG_VERSION    1
#define GT_SEG_HEADER_SZ  16
#define GT_REC_MAGIC      0xA7
#define GT_REC_VERSION    1
#define GT_REC_SIZE       24

typedef enum { GT_REC_DATA = 0x01, GT_REC_GAP = 0x02 } gt_rec_type;

/* 24 B record: written to disk, and also sent hub -> storage unchanged.
 *
 * Wire layout, little-endian, written byte by byte (never by struct copy,
 * so compiler padding can't leak onto the wire or the disk):
 *   off 0  magic      GT_REC_MAGIC
 *   off 1  type       GT_REC_DATA / GT_REC_GAP
 *   off 2  version    GT_REC_VERSION
 *   off 3  sensor_id  LIGHT / SOIL; a GAP may also use GT_SENSOR_ALL
 *   off 4  seq        u32, hub-assigned
 *   off 8  timestamp  u64, hub receive time (GAP: gap start), us since epoch
 *   off 16 value      u32
 *   off 20 crc32      u32, CRC-32 over bytes 0-19
 * Note: type and version are in the opposite order from the 16 B message
 * in ipc.h. Magic, version and CRC are not struct fields. */
typedef struct {
    uint8_t  type;       /* gt_rec_type */
    uint8_t  sensor_id;  /* gt_sensor_id */
    uint32_t seq;
    uint64_t timestamp_us;
    uint32_t value;      /* DATA: raw count; GAP: refused-reading count */
} gt_record;

/* Standard CRC-32 (the one zlib and Ethernet use) over `len` bytes of `buf`.
 * `const void *` means "a pointer to bytes of any type, read-only". */
uint32_t  gt_crc32(const void *buf, size_t len);

/* Write `rec` as 24 bytes into `out`, including magic, version and CRC.
 * Returns GT_ERR_INVAL for NULL args, an unknown type, or a bad sensor_id;
 * `out` is untouched on failure. */
gt_status gt_record_encode(const gt_record *rec, uint8_t out[GT_REC_SIZE]);

/* Read 24 bytes into `rec`. Returns GT_ERR_CORRUPT for a bad magic, version,
 * type, sensor_id or CRC, and GT_ERR_INVAL for NULL args; `rec` is untouched
 * on failure. */
gt_status gt_record_decode(const uint8_t in[GT_REC_SIZE], gt_record *rec);

#endif
#ifndef SENSOR_HEALTH_H
#define SENSOR_HEALTH_H

#include <stdint.h>
#include "ipc.h"

/* Offline/online tracking for one sensor (DESIGN.md failure-mode table,
 * Sensor (I2C) row). Pure logic: the caller passes each read result and a
 * monotonic time in ms, and logs the returned transition. Times are
 * uint64_t because a 32-bit ms clock wraps after about 49.7 days. */
#define GT_HEALTH_OFFLINE_AFTER 10     /* consecutive failed reads -> offline */
#define GT_HEALTH_RETRY_MS      5000   /* probe period while offline */

typedef enum { GT_HEALTH_ONLINE, GT_HEALTH_OFFLINE } gt_health_state;

/* Returned by gt_health_record; the caller logs sensor_offline / sensor_online. */
typedef enum {
    GT_HEALTH_EV_NONE,
    GT_HEALTH_EV_OFFLINE,
    GT_HEALTH_EV_ONLINE
} gt_health_event;

typedef struct {
    gt_health_state state;
    uint32_t        consecutive_fails;
    uint64_t        next_probe_ms;     /* valid only while OFFLINE */
} gt_health;

void            gt_health_init(gt_health *health);
/* Online: always 1. Offline: 1 only once now_ms >= next_probe_ms. NULL -> 0. */
int             gt_health_should_read(const gt_health *health, uint64_t now_ms);
/* Feed one read result; any non-GT_OK is a failure (a failed gt_light_read
 * already includes the driver's retries). NULL -> GT_HEALTH_EV_NONE. */
gt_health_event gt_health_record(gt_health *health, gt_status read_result, uint64_t now_ms);

/* Log event names (DESIGN.md failure-mode table, Sensor (I2C) row).
 * i2c_read_error is logged on every failed read, not only on a transition. */
#define GT_HEALTH_I2C_READ_ERROR "i2c_read_error"
/* "sensor_offline" / "sensor_online"; NULL for GT_HEALTH_EV_NONE or an
 * unknown value (nothing to log). */
const char     *gt_health_event_name(gt_health_event event);

#endif
#ifndef IPC_SOCK_H
#define IPC_SOCK_H

#include <stddef.h>
#include <stdint.h>
#include "ipc.h"

/* Socket seam for the IPC client, the same idea as gt_i2c_ops in i2c_bus.h.
 *
 * The client (src/ipc_client.c) talks to hub.sock only through these ops,
 * so tests can swap in tests/fake_sock.h and run every reconnect, backoff
 * and overflow path with no hub and no real waiting. src/ipc_sock.c is the
 * only file that makes socket system calls.
 *
 * The socket is AF_UNIX SOCK_SEQPACKET: the kernel keeps message
 * boundaries, so one send() is one whole 16 B message. Every op is
 * non-blocking, so a slow or dead hub never stalls the sampler. */
typedef struct {
    /* Open a socket and connect to the hub. GT_OK, or GT_ERR_IO if the hub
     * isn't there (ENOENT / ECONNREFUSED): the client retries later. */
    gt_status (*connect)(void *ctx);
    /* Send one whole frame. GT_OK when the kernel took it; GT_ERR_FULL on
     * EAGAIN (the hub is alive but its buffer is full: keep the frame and
     * try again later); GT_ERR_IO on EPIPE / ECONNRESET (the hub is gone:
     * disconnect and reconnect). */
    gt_status (*send)(void *ctx, const uint8_t *buf, size_t len);
    /* Close the current connection but keep ctx, so connect() can be
     * called again. Safe to call when not connected. */
    void      (*disconnect)(void *ctx);
    /* Close any connection and free ctx. Called exactly once, by
     * gt_ipc_client_close. */
    void      (*destroy)(void *ctx);
} gt_sock_ops;

/* Linux impl: prepares a ctx for `path` (e.g. "/run/plantpi/hub.sock") but
 * does not connect yet, so a hub that isn't up is not an error here.
 * GT_ERR_INVAL for a NULL/empty path or one too long for sun_path (108 B);
 * GT_ERR_NOMEM if the ctx can't be allocated. Outputs are untouched on
 * failure.
 *
 * The outputs are pointer-to-pointer (`**`) because the function hands back
 * two pointers: `*ops_out` is set to the ops table and `*ctx_out` to the new
 * ctx. A plain `*` parameter could only change what the function's own copy
 * points at; `**` lets it change the caller's pointer. */
gt_status gt_ipc_sock_linux(const char *path, const gt_sock_ops **ops_out, void **ctx_out);

/* A client over any socket ops: gt_ipc_client_open uses the Linux ops, and
 * tests pass tests/fake_sock.h (like gt_light_open_bus for the I2C seam).
 * Does not connect yet. Once ops is non-NULL the client owns ctx and calls
 * ops->destroy(ctx) exactly once: from gt_ipc_client_close, or straight
 * away if the client can't be allocated (returns NULL). NULL ops also
 * return NULL, but the ctx is left alone: there's no destroy to call, so
 * the caller still owns it. Declared here, not in ipc.h, because ipc.h can't see
 * gt_sock_ops without the two headers including each other. */
gt_ipc_client *gt_ipc_client_open_ops(const gt_sock_ops *ops, void *ctx);

#endif
# make predefines CC=cc, so `?=` never fires; only replace make's default.
ifeq ($(origin CC),default)
CC := gcc
endif
BUILD ?= build
BASE_CFLAGS := -std=c17 -D_POSIX_C_SOURCE=200809L -Wall -Wextra -Werror -g -O1 -Iinclude -Itests -pthread
CFLAGS := $(BASE_CFLAGS) $(EXTRA_CFLAGS)

# Library sources are everything in src/ (process main()s should live in
# src/<name>_main.c and be listed in MAIN_SRC so tests don't link them).
MAIN_SRC := $(wildcard src/*_main.c)
LIB_SRC := $(filter-out $(MAIN_SRC),$(wildcard src/*.c))
HEADERS := $(wildcard include/*.h tests/*.h)

# Every tests/test_*.c becomes $(BUILD)/test_* linked against all of LIB_SRC.
TEST_SRC := $(wildcard tests/test_*.c)
TEST_BINS := $(patsubst tests/%.c,$(BUILD)/%,$(TEST_SRC))

VALGRIND := valgrind --leak-check=full --show-leak-kinds=all --error-exitcode=1

all: $(TEST_BINS) $(BUILD)/light_probe $(BUILD)/hub_listen

$(BUILD)/%: tests/%.c $(LIB_SRC) $(HEADERS)
	@mkdir -p $(BUILD)
	$(CC) $(CFLAGS) $(LIB_SRC) $< -o $@

# On-Pi BH1750 bring-up check (see src/light_probe_main.c). Not run by
# `make test`: it needs real I2C hardware.
$(BUILD)/light_probe: src/light_probe_main.c $(LIB_SRC) $(HEADERS)
	@mkdir -p $(BUILD)
	$(CC) $(CFLAGS) $(LIB_SRC) $< -o $@

light_probe: $(BUILD)/light_probe

# On-Pi stand-in for the hub on hub.sock (see src/hub_listen_main.c). Not
# run by `make test`: it serves until killed.
$(BUILD)/hub_listen: src/hub_listen_main.c $(LIB_SRC) $(HEADERS)
	@mkdir -p $(BUILD)
	$(CC) $(CFLAGS) $(LIB_SRC) $< -o $@

hub_listen: $(BUILD)/hub_listen

# Every test binary runs even if an earlier one fails; failures are listed
# at the end and the target still exits nonzero for CI.
test: $(TEST_BINS)
	@failed=""; for b in $(TEST_BINS); do echo "== $$b"; ./$$b || failed="$$failed $$b"; done; \
	if [ -n "$$failed" ]; then echo "FAILED:$$failed"; exit 1; fi

# Sanitizers get their own build dirs so they never reuse plain objects.
asan:
	$(MAKE) test BUILD=build/asan \
	  EXTRA_CFLAGS="-fsanitize=address,undefined -fno-omit-frame-pointer"

ubsan:
	$(MAKE) test BUILD=build/ubsan \
	  EXTRA_CFLAGS="-fsanitize=undefined -fno-sanitize-recover=undefined"

# valgrind and ASan don't mix, so memcheck runs the plain build.
memcheck: $(TEST_BINS)
	@failed=""; for b in $(TEST_BINS); do echo "== valgrind $$b"; $(VALGRIND) ./$$b || failed="$$failed $$b"; done; \
	if [ -n "$$failed" ]; then echo "FAILED:$$failed"; exit 1; fi

clean:
	rm -rf build

.PHONY: all test asan ubsan memcheck clean light_probe hub_listen
# Problem memo -- The Green Thumb (Lily Heeren, Lucas Jenkins)

## The user
Our device can be used by any person who is a household plant owner and would like to monitor their plants for better care of them. When it comes to the place, our device can be used in any household that holds plants and would like to monitor them more deeply.

## The problem
The problem we are trying to resolve with our device is incorrect care of plants. Household plants can be quite expensive and time consuming. While most people might think plants are easy to keep alive, a lot of times they can be over-watered, get the incorrect amount of sun, or overall not live as long as they could because of how they are cared for. These problems can happen a lot and the main cost is monetary, time, and the life of the plants themselves.

## Why a device
This device is a good idea because we would be able to monitor and report about a plant at all times, this would allow the user to not constantly monitor their plant and overall give their plants better lifespans. A phone app can not reasonably solve the problem we have and the hardware is essential so we can monitor the stats of the plants directly.

## The sensors
The sensors we plan to use in our project are light and moisture sensors. The light sensors will allow us to monitor how much sunlight the plant is receiving and the moisture sensor will allow us to monitor when the plant will need water, or if it is being over-wattered. We also may decide to use temperature sensors to read what temperature the plant and surrounding area is for optimal plant life. These cooperate with our device as they are essential to monitoring the health and needs of the plant.

## The mechanisms
The first mechanism that we plan to build from the list is mechanism D becuase the memory problem is a high potential if our device suddly stops or looses power, the ability to not loose information when that happens is important to the success of our project. The second mechanism we plan to build is mechanism E becuase splitting our problem up into more self-suffiecnt pieces is better for the overall outcoem of our project and will allow us to test more effiecntly.

## The risk
Our software heavily relies on the data we gather from our device, so if one piece of the data or software is slightly off then we could have massive problems. Overall, our most likely sink is poor execution of software with the data collected.

