static int check_failures;

#define CHECK(cond)                                                     \
    do {                                                                \
        if (!(cond)) {                                                  \
            fprintf(stderr, "    %s:%d: CHECK failed: %s\n",            \
                    __FILE__, __LINE__, #cond);                         \
