#include "log_record.h"

#include <stddef.h>

/* The standard CRC-32 polynomial (zlib, Ethernet, PNG) in reflected form:
 * bits are processed lowest first, so the polynomial is bit-reversed. */
#define CRC32_POLY_REFLECTED 0xEDB88320u

/* Write `value` into out[0..3], lowest byte first. */
static void put_u32_le(uint8_t *out, uint32_t value)
{
    out[0] = (uint8_t)(value);
    out[1] = (uint8_t)(value >> 8);
    out[2] = (uint8_t)(value >> 16);
    out[3] = (uint8_t)(value >> 24);
}

/* Write a u64 as two little-endian u32 halves, low half first, so out[0..7]
 * is lowest byte first overall. */
static void put_u64_le(uint8_t *out, uint64_t value)
{
    put_u32_le(&out[0], (uint32_t)(value));
    put_u32_le(&out[4], (uint32_t)(value >> 32));
}

/* Read in[0..3], lowest byte first. Each byte is widened to uint32_t
 * before shifting, so a shift by 24 can't overflow an int. */
static uint32_t get_u32_le(const uint8_t *in)
{
    return (uint32_t)in[0]
         | ((uint32_t)in[1] << 8)
         | ((uint32_t)in[2] << 16)
         | ((uint32_t)in[3] << 24);
}

/* Read a u64 from two little-endian u32 halves, low half first. The high
 * half is widened to uint64_t before the 32-bit shift, because shifting a
 * 32-bit value by 32 is undefined in C. */
static uint64_t get_u64_le(const uint8_t *in)
{
    return (uint64_t)get_u32_le(&in[0])
         | ((uint64_t)get_u32_le(&in[4]) << 32);
}

/* Whether type and sensor_id are allowed in a record: DATA or GAP, from the
 * light or soil sensor. GT_SENSOR_ALL is allowed only in a GAP, because
 * storage records one gap for every sensor when its own queue is full; a
 * DATA reading always comes from one sensor. Shared so encode refuses
 * exactly what decode would reject. */
static int fields_valid(uint8_t type, uint8_t sensor_id)
{
    int type_ok = type == GT_REC_DATA || type == GT_REC_GAP;
    int one_sensor = sensor_id == GT_SENSOR_LIGHT || sensor_id == GT_SENSOR_SOIL;
    int all_sensors_gap = type == GT_REC_GAP && sensor_id == GT_SENSOR_ALL;
    return type_ok && (one_sensor || all_sensors_gap);
}

/* Standard CRC-32, one bit at a time (no lookup table: a record is only 20
 * bytes, so speed doesn't matter). The running value starts at 0xFFFFFFFF
 * and is inverted at the end, so the empty input gives 0. In C, a
 * `const void *` converts to `const uint8_t *` without a cast, which lets
 * callers pass any buffer. */
uint32_t gt_crc32(const void *buf, size_t len)
{
    const uint8_t *bytes = buf;
    uint32_t crc = 0xFFFFFFFFu;

    /* invariant: crc is the (not yet inverted) CRC of bytes[0..byte_index) */
    for (size_t byte_index = 0; byte_index < len; byte_index++) {
        crc ^= bytes[byte_index];
        /* invariant: the low bit_count bits of this byte have been divided out */
        for (int bit_count = 0; bit_count < 8; bit_count++) {
            if (crc & 1u) {
                crc = (crc >> 1) ^ CRC32_POLY_REFLECTED;
            } else {
                crc >>= 1;
            }
        }
    }
    return crc ^ 0xFFFFFFFFu;
}

/* Bytes 0-19 are covered by the CRC; the CRC itself sits at 20-23. */
#define CRC_COVERED_LEN 20

/* Pack `rec` into the 24 bytes in `out`, then seal them with the CRC of
 * bytes 0-19. Everything is checked before the first byte is written, so a
 * rejected record leaves `out` exactly as it was. GT_ERR_INVAL on NULL args
 * or a bad type/sensor_id. */
gt_status gt_record_encode(const gt_record *rec, uint8_t out[GT_REC_SIZE])
{
    if (rec == NULL || out == NULL) {
        return GT_ERR_INVAL;
    }
    if (!fields_valid(rec->type, rec->sensor_id)) {
        return GT_ERR_INVAL;
    }

    out[0] = GT_REC_MAGIC;
    out[1] = rec->type;          /* type before version: the reverse of the message */
    out[2] = GT_REC_VERSION;
    out[3] = rec->sensor_id;
    put_u32_le(&out[4], rec->seq);
    put_u64_le(&out[8], rec->timestamp_us);
    put_u32_le(&out[16], rec->value);
    put_u32_le(&out[20], gt_crc32(out, CRC_COVERED_LEN));
    return GT_OK;
}

/* Unpack 24 bytes from `in` into `rec`. The CRC is checked first, so no
 * field of a damaged record is trusted; then magic, version, type and
 * sensor_id. `rec` is written only once every check has passed.
 * GT_ERR_INVAL on NULL args (a caller bug); GT_ERR_CORRUPT on any bad byte
 * (storage refuses it; recovery truncates the log at the first such record). */
gt_status gt_record_decode(const uint8_t in[GT_REC_SIZE], gt_record *rec)
{
    if (in == NULL || rec == NULL) {
        return GT_ERR_INVAL;
    }
    if (get_u32_le(&in[20]) != gt_crc32(in, CRC_COVERED_LEN)) {
        return GT_ERR_CORRUPT;
    }
    if (in[0] != GT_REC_MAGIC || in[2] != GT_REC_VERSION || !fields_valid(in[1], in[3])) {
        return GT_ERR_CORRUPT;
    }

    rec->type = in[1];
    rec->sensor_id = in[3];
    rec->seq = get_u32_le(&in[4]);
    rec->timestamp_us = get_u64_le(&in[8]);
    rec->value = get_u32_le(&in[16]);
    return GT_OK;
}
};

/* Rewrite bytes 20-23 with the CRC of bytes 0-19, little-endian. Used after
 * breaking a header byte so the record's CRC is still valid: otherwise the
 * CRC check alone would reject it, and the magic/version/type/sensor checks
 * would never be exercised. */
static void reseal_crc(uint8_t wire[GT_REC_SIZE])
{
    uint32_t crc = gt_crc32(wire, 20);
    wire[20] = (uint8_t)(crc);
    wire[21] = (uint8_t)(crc >> 8);
    wire[22] = (uint8_t)(crc >> 16);
    wire[23] = (uint8_t)(crc >> 24);
}

/* Decode `wire` and check it is rejected as corrupt with the output left
 * exactly as it was (pre-filled with 0x5A). */
static void check_rejected_untouched(const uint8_t wire[GT_REC_SIZE])
{
    gt_record decoded, untouched;
    memset(&decoded, 0x5A, sizeof decoded);
    memset(&untouched, 0x5A, sizeof untouched);

    CHECK_EQ(gt_record_decode(wire, &decoded), GT_ERR_CORRUPT);
    CHECK(memcmp(&decoded, &untouched, sizeof decoded) == 0);
}

/* ---- RCD-02: hand-built bytes decode ----
 * Checks decode, and the CRC, against the documented layout directly, so
 * a matching bug in encode and decode (which RCD-01 alone would miss)
 * still fails. */
static void test_rcd02_hand_built_bytes(void)
{
    gt_record decoded;

    CHECK_EQ(gt_record_decode(VALID_WIRE, &decoded), GT_OK);
    CHECK_EQ(decoded.type, GT_REC_DATA);
    CHECK_EQ(decoded.sensor_id, GT_SENSOR_LIGHT);
    CHECK_EQ(decoded.seq, 0x04030201u);
    CHECK(decoded.timestamp_us == 0x0C0B0A0908070605u);
    CHECK_EQ(decoded.value, 0x100F0E0Du);
}

/* ---- RCD-03: a bad magic byte is rejected ----
 * 0xA6 is the 16 B message's magic: a message must never be stored as a
 * record. The CRC is resealed, so only the magic check can catch it. */
static void test_rcd03_bad_magic_rejected(void)
{
    uint8_t wire[GT_REC_SIZE];
    memcpy(wire, VALID_WIRE, sizeof wire);
    wire[0] = 0xA6;
    reseal_crc(wire);

    check_rejected_untouched(wire);
}

/* ---- RCD-04: a bad version byte is rejected ----
 * A record from a newer layout must not be misread as version 1. */
static void test_rcd04_bad_version_rejected(void)
{
    uint8_t wire[GT_REC_SIZE];
    memcpy(wire, VALID_WIRE, sizeof wire);
    wire[2] = GT_REC_VERSION + 1;
    reseal_crc(wire);

    check_rejected_untouched(wire);
}

/* ---- RCD-05: an unknown type is rejected ----
 * Types 0 and 3 are neither DATA nor GAP. DESIGN.md: "Any record with an
 * unknown record_type is treated as corrupt." */
static void test_rcd05_unknown_type_rejected(void)
{
    const uint8_t unknown_types[] = { 0x00, 0x03 };

    for (size_t type_index = 0; type_index < sizeof unknown_types; type_index++) {
        uint8_t wire[GT_REC_SIZE];
        memcpy(wire, VALID_WIRE, sizeof wire);
        wire[1] = unknown_types[type_index];
        reseal_crc(wire);

        check_rejected_untouched(wire);
    }
}

/* ---- RCD-06: a bad sensor_id is rejected ----
 * Mirrors RCE-07: 0 (ALL) is invalid for DATA, and 3 is no sensor for
 * either type. Each case is one {type, sensor_id} pair. `uint8_t
 * bad_pairs[][2]` is a 2-D array: a list of rows, each row exactly 2
 * bytes; the compiler counts the rows from the initializer. */
static void test_rcd06_bad_sensor_id_rejected(void)
{
    const uint8_t bad_pairs[][2] = {
        { GT_REC_DATA, GT_SENSOR_ALL },
        { GT_REC_DATA, 3 },
        { GT_REC_GAP,  3 },
    };
    size_t pair_count = sizeof bad_pairs / sizeof bad_pairs[0];

    for (size_t pair_index = 0; pair_index < pair_count; pair_index++) {
        uint8_t wire[GT_REC_SIZE];
        memcpy(wire, VALID_WIRE, sizeof wire);
        wire[1] = bad_pairs[pair_index][0];
        wire[3] = bad_pairs[pair_index][1];
        reseal_crc(wire);

        check_rejected_untouched(wire);
    }
}

/* ---- RCD-07: a CRC mismatch is rejected ----
 * One payload byte (the value's low byte) is damaged and the CRC is NOT
 * resealed: what a torn write or a bad SD sector leaves behind. */
static void test_rcd07_crc_mismatch_rejected(void)
{
    uint8_t wire[GT_REC_SIZE];
    memcpy(wire, VALID_WIRE, sizeof wire);
    wire[16] ^= 0x01;

    check_rejected_untouched(wire);
}

/* ---- RCD-08: NULL arguments are rejected ----
 * GT_ERR_INVAL (a caller bug), not GT_ERR_CORRUPT (bad bytes). */
static void test_rcd08_null_args(void)
{
    gt_record decoded;

    CHECK_EQ(gt_record_decode(NULL, &decoded), GT_ERR_INVAL);
    CHECK_EQ(gt_record_decode(VALID_WIRE, NULL), GT_ERR_INVAL);
}

static const test_case_t tests[] = {
    {"RCD-01", "decode undoes encode", test_rcd01_round_trip},
    {"RCD-02", "hand-built bytes decode", test_rcd02_hand_built_bytes},
    {"RCD-03", "a bad magic byte is rejected", test_rcd03_bad_magic_rejected},
    {"RCD-04", "a bad version byte is rejected", test_rcd04_bad_version_rejected},
    {"RCD-05", "an unknown type is rejected", test_rcd05_unknown_type_rejected},
    {"RCD-06", "a bad sensor_id is rejected", test_rcd06_bad_sensor_id_rejected},
    {"RCD-07", "a CRC mismatch is rejected", test_rcd07_crc_mismatch_rejected},
    {"RCD-08", "NULL arguments are rejected", test_rcd08_null_args},
};

int main(void)
