 * does. */
static inline gt_status fake_fs_ftruncate(void *ctx, int handle, uint64_t len)
{
    fake_fs *fs = ctx;
    fs->ftruncate_calls++;
    fake_file *file = fake_fs_handle(fs, handle);
    if (file == NULL) {
        return GT_ERR_IO;
    }
    if (fs->ftruncate_calls == fs->fail_ftruncate_call) {
        return GT_ERR_IO;
    }
