    CHECK_EQ(fs.fsync_calls, 0);
    CHECK_EQ(fs.rename_calls, 0);
    CHECK_EQ(fake_fs_file(&fs, SEGMENT_NAME)->len, len);
    CHECK(memcmp(fake_fs_file(&fs, SEGMENT_NAME)->data, segment, len) == 0);
