    gt_status status = read_whole_file(ops, ctx, handle, &bytes, &len);

    gt_scan_result scan;
    memset(&scan, 0, sizeof scan);   /* header_ok 0: an empty file has no header */
    if (status == GT_OK && bytes != NULL) {
