#define SEGMENT_BUF_SIZE    (GT_SEG_HEADER_SZ + (SEGMENT_MAX_RECORDS + 1) * GT_REC_SIZE)
#define RECORD_OFFSET(record_index) (GT_SEG_HEADER_SZ + (record_index) * GT_REC_SIZE)

