 * caller logs the matching event name. */
#define GT_STORAGE_EV_SEQ_REJECTED 0x1u   /* a duplicate or old seq: log seq_rejected */
#define GT_STORAGE_EV_RECOVERY_GAP 0x2u   /* seqs were missing: log recovery_gap */

