    int open_flags = O_RDWR | O_CLOEXEC | ((flags & GT_FILE_CREATE) ? O_CREAT : 0);
    int fd;
    /* Repeat only while a signal interrupted the call. */
    do {
        fd = openat(dir->dir_fd, name, open_flags, 0644);
