}

static void file_destroy(void *ctx)
{
    linux_dir *dir = ctx;
    close(dir->dir_fd);
    free(dir);
}

gt_status gt_file_ops_linux(const char *dir, const gt_file_ops **ops_out, void **ctx_out)
{
    static const gt_file_ops ops = {
        .open      = file_open,
        .size      = file_size,
        .pread     = file_pread,
        .pwrite    = file_pwrite,
        .fsync     = file_fsync,
        .ftruncate = file_ftruncate,
        .close     = file_close,
        .fsync_dir = file_fsync_dir,
