typedef struct {
    char dir[32];    /* "/tmp/gt-lbd-XXXXXX", the X's filled in by mkdtemp */
    char path[64];   /* dir + "/test.sock" */
} bind_dir;

/* Make a fresh directory. Returns 1 on success, 0 on failure. */
