/* Take the lock for the fixture's path, checking it works. */
static int take_lock(const bind_dir *fixture)
{
    int lock_fd = -1, already_running = 0;
    CHECK_EQ(gt_listen_lock(fixture->path, &lock_fd, &already_running), GT_OK);
    return lock_fd;
