    CHECK(event.reason != NULL && strcmp(event.reason, "write_failed") == 0);
    CHECK_EQ(gt_storage_event_describe(GT_STORAGE_EV_QUEUE_FULL, &event), GT_OK);
    CHECK(event.reason != NULL && strcmp(event.reason, "queue_full") == 0);

