        close(conn_fd);
        log(log_ctx, GT_LOG_WARN, "hub_duplicate_client", NULL);
    }
    if (!send_resume(storage, new_fd, log, log_ctx)) {
        close(new_fd);
        log(log_ctx, GT_LOG_INFO, "hub_disconnected", NULL);
        return -1;
    }
