}

gt_status gt_storage_serve(gt_storage *storage, int listen_fd, int stop_fd,
                           gt_storage_log_fn log, void *log_ctx)
{
    if (storage == NULL || log == NULL || listen_fd < 0 || stop_fd < 0) {
